    siderealMonth: 27.321661,
    synodicMonth: 29.530589,
    siderealYear: 365.256363,
    moonDistanceKm: 384400,
    moonRecessionCmPerYear: 3.8,
    dayHours: 24,
    sunAngularMin: 31.6,          /* at aphelion */
    sunAngularMax: 32.7,          /* at perihelion */
    moonAngularMin: 29.4,
    moonAngularMax: 33.5,
