    if (!pa || !pb) return now;
    var r0 = { x: pb.x - pa.x, y: pb.y - pa.y, z: pb.z - pa.z };
    var dr = { x: (B.p.x - A.p.x) - r0.x,
               y: (B.p.y - A.p.y) - r0.y,
               z: (B.p.z - A.p.z) - r0.z };
