      var k1 = Math.floor(acc / (2 * Math.PI));
      if (k1 !== k0) {
        var frac = (2 * Math.PI * Math.max(k0, k1) - before) / (d || 1e-12);
        crossings.push(fr[i - 1].t + (fr[i].t - fr[i - 1].t) * frac);
      }
