    try { S = T.build(spec); } catch (e) { S = null; }
    if (!S) return null;

    var seconds = opts.seconds || T.seconds;
    S.key = key;
    S.pal = window.SPReel.pal(opts.palette || "gold");
    S.seconds = seconds;
